#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <tlhelp32.h>
#include <iostream>
DWORD FindProcess(const wchar_t* exe){HANDLE s=CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS,0);if(s==INVALID_HANDLE_VALUE)return 0;PROCESSENTRY32W p{sizeof(p)};DWORD pid=0;if(Process32FirstW(s,&p)){do{if(!_wcsicmp(p.szExeFile,exe)){pid=p.th32ProcessID;break;}}while(Process32NextW(s,&p));}CloseHandle(s);return pid;}
int wmain(){DWORD pid=FindProcess(L"NOBU6HD_JP.exe");if(!pid){std::wcerr<<L"NOBU6HD_JP.exe is not running. Start the game first.\n";return 1;}wchar_t dll[MAX_PATH]{};DWORD n=GetFullPathNameW(L"HookDLL.dll",MAX_PATH,dll,nullptr);if(!n||n>=MAX_PATH){std::wcerr<<L"HookDLL.dll not found.\n";return 2;}HANDLE p=OpenProcess(PROCESS_CREATE_THREAD|PROCESS_QUERY_INFORMATION|PROCESS_VM_OPERATION|PROCESS_VM_WRITE|PROCESS_VM_READ,FALSE,pid);if(!p){std::wcerr<<L"OpenProcess failed: "<<GetLastError()<<L"\n";return 3;}SIZE_T bytes=(wcslen(dll)+1)*sizeof(wchar_t);void*mem=VirtualAllocEx(p,nullptr,bytes,MEM_COMMIT|MEM_RESERVE,PAGE_READWRITE);if(!mem){CloseHandle(p);return 4;}if(!WriteProcessMemory(p,mem,dll,bytes,nullptr)){VirtualFreeEx(p,mem,0,MEM_RELEASE);CloseHandle(p);return 5;}auto load=(LPTHREAD_START_ROUTINE)GetProcAddress(GetModuleHandleW(L"kernel32.dll"),"LoadLibraryW");HANDLE t=CreateRemoteThread(p,nullptr,0,load,mem,0,nullptr);if(!t){VirtualFreeEx(p,mem,0,MEM_RELEASE);CloseHandle(p);return 6;}WaitForSingleObject(t,5000);DWORD ec=0;GetExitCodeThread(t,&ec);VirtualFreeEx(p,mem,0,MEM_RELEASE);CloseHandle(t);CloseHandle(p);if(!ec){std::wcerr<<L"DLL load failed.\n";return 7;}std::wcout<<L"Injected. Log: %TEMP%\\nobu_gdi_trace.txt\n";return 0;}
